package com.taskflow.userservice.config;
import jakarta.servlet.http.HttpServletRequest; import jakarta.servlet.http.HttpServletResponse; import java.io.IOException; import java.time.Instant; import java.util.Map; import org.springframework.http.MediaType; import org.springframework.security.core.AuthenticationException; import org.springframework.security.web.AuthenticationEntryPoint; import org.springframework.security.web.access.AccessDeniedHandler; import org.springframework.stereotype.Component; import com.fasterxml.jackson.databind.ObjectMapper;
@Component public class SecurityErrorHandlers implements AuthenticationEntryPoint,AccessDeniedHandler { private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(SecurityErrorHandlers.class); private final ObjectMapper mapper; public SecurityErrorHandlers(ObjectMapper mapper){this.mapper=mapper;} private void write(HttpServletRequest req,HttpServletResponse res,int status,String error,String message)throws IOException{res.setStatus(status);res.setContentType(MediaType.APPLICATION_JSON_VALUE);mapper.writeValue(res.getOutputStream(),Map.of("timestamp",Instant.now().toString(),"status",status,"error",error,"message",message,"validationErrors",Map.of(),"path",req.getRequestURI()));} public void commence(HttpServletRequest req,HttpServletResponse res,AuthenticationException ex)throws IOException{log.warn("Authentication rejected method={} path={}",req.getMethod(),req.getRequestURI());write(req,res,401,"Unauthorized","Authentication is required or the access token is invalid or expired");} public void handle(HttpServletRequest req,HttpServletResponse res,org.springframework.security.access.AccessDeniedException ex)throws IOException{log.warn("Access denied method={} path={}",req.getMethod(),req.getRequestURI());write(req,res,403,"Forbidden","You are not allowed to access this resource");} }
